         ssd1681_command(0x12u) &&
         ssd1681_wait_ready(0u, SSD1681_READY_TIMEOUT_MS) &&
         ssd1681_point_probe_set_window(&window, 0x80u) &&
         ssd1681_command_data(0x3Fu, &ssd1681_custom_mode2_transition_lut[153], 1u) &&
         ssd1681_command_data(0x03u, &ssd1681_custom_mode2_transition_lut[154], 1u) &&
         ssd1681_command_data(0x04u, &ssd1681_custom_mode2_transition_lut[155], 3u) &&
         ssd1681_command_data(0x2Cu, &ssd1681_custom_mode2_transition_lut[158], 1u) &&
         ssd1681_command_data(0x32u, ssd1681_custom_mode2_transition_lut, 153u);
