static void ssd1681_r10_count_classes(const ssd1681_window_t *window,
                                       ssd1681_r10_frame_record_t *record)
{
    record->ww = 0u;
    record->wb = 0u;
    record->bw = 0u;
    record->bb = 0u;
    for (uint16_t y = window->y_start; y <= window->y_end; ++y) {
        const size_t row_offset = (size_t)y * SSD1681_BYTES_PER_ROW;
        for (uint8_t x = window->x_start_byte; x <= window->x_end_byte; ++x) {
            const uint8_t previous = s_previous_frame[row_offset + x];
            const uint8_t current = s_frame[row_offset + x];
            for (uint8_t mask = 0x80u; mask != 0u; mask >>= 1u) {
                const bool old_white = (previous & mask) != 0u;
                const bool new_white = (current & mask) != 0u;
                if (old_white && new_white) {
                    ++record->ww;
                } else if (old_white) {
                    ++record->wb;
                } else if (new_white) {
                    ++record->bw;
                } else {
                    ++record->bb;
                }
            }
        }
    }
}

static bool ssd1681_r10_window_valid(const ssd1681_window_t *window,
                                      uint8_t previous_x,
                                      uint8_t current_x)
{
    (void)previous_x;
    (void)current_x;
    return window != NULL && window->changed &&
           window->x_start_byte == SSD1681_R10_CORRIDOR_X_START_BYTE &&
           window->x_end_byte == SSD1681_R10_CORRIDOR_X_END_BYTE &&
           window->y_start == SSD1681_R10_CORRIDOR_Y_START &&
           window->y_end == SSD1681_R10_CORRIDOR_Y_END &&
           ssd1681_window_byte_count(window) == SSD1681_R10_CORRIDOR_BYTES;
}

static ssd1681_window_t ssd1681_r10_corridor_from_difference(
    const ssd1681_window_t *difference)
{
    const ssd1681_window_t corridor = {
        .x_start_byte = SSD1681_R10_CORRIDOR_X_START_BYTE,
        .x_end_byte = SSD1681_R10_CORRIDOR_X_END_BYTE,
        .y_start = SSD1681_R10_CORRIDOR_Y_START,
        .y_end = SSD1681_R10_CORRIDOR_Y_END,
        .changed = difference != NULL && difference->changed,
    };

    if (difference == NULL || !difference->changed ||
        difference->x_start_byte < corridor.x_start_byte ||
        difference->x_end_byte > corridor.x_end_byte ||
        difference->y_start < corridor.y_start ||
        difference->y_end > corridor.y_end) {
        return (ssd1681_window_t){0};
    }
    return corridor;
}

static bool ssd1681_r10_execute_frame(uint8_t previous_x,
                                      uint8_t current_x,
                                      ssd1681_r10_frame_record_t *record)
{
    static const uint8_t mode2_display[] = {0xCFu};
    bool ok;

    if (record == NULL || !ssd1681_r10_position_valid(current_x) ||
        (previous_x != SSD1681_R10_WHITE_POSITION &&
         (!ssd1681_r10_position_valid(previous_x) ||
          (previous_x > current_x ? previous_x - current_x : current_x - previous_x) !=
              COMP_R10_BALL_DIAGNOSTIC_X_STEP))) {
        return false;
    }

    memset(record, 0, sizeof(*record));
    ssd1681_r10_render_frame(s_previous_frame, previous_x);
    ssd1681_r10_render_frame(s_frame, current_x);
    s_previous_frame_valid = true;
    {
        const ssd1681_window_t difference = ssd1681_window_from_difference();
        record->window = ssd1681_r10_corridor_from_difference(&difference);
    }
    record->window_bytes = ssd1681_window_byte_count(&record->window);
    if (!ssd1681_r10_window_valid(&record->window, previous_x, current_x) ||
        ssd1681_r10_frame_sha256(previous_x) == NULL ||
        ssd1681_r10_frame_sha256(current_x) == NULL) {
        return false;
    }
    ssd1681_r10_count_classes(&record->window, record);
    if ((previous_x == SSD1681_R10_WHITE_POSITION &&
         (record->ww != 464u || record->wb != 112u || record->bw != 0u || record->bb != 0u)) ||
        (previous_x != SSD1681_R10_WHITE_POSITION &&
         (record->ww != 376u || record->wb != 88u || record->bw != 88u || record->bb != 24u))) {
        return false;
    }

    ok = ssd1681_point_probe_set_window(&record->window, 0x80u) &&
         ssd1681_write_plane_region(0x26u, s_previous_frame, &record->window) &&
         ssd1681_point_probe_set_window(&record->window, 0x80u) &&
         ssd1681_write_plane_region(0x24u, s_frame, &record->window) &&
         ssd1681_command_data(0x22u, mode2_display, sizeof(mode2_display)) &&
         ssd1681_command(0x20u);
    if (ok) {
        const uint32_t busy_start = HAL_GetTick();
        ok = ssd1681_wait_refresh_complete(0u, SSD1681_R10_BUSY_LIMIT_MS);
        record->busy_elapsed_ms = HAL_GetTick() - busy_start;
        ok = ok && record->busy_elapsed_ms <= SSD1681_R10_BUSY_LIMIT_MS;
    }
    if (ok) {
        ok = ssd1681_point_probe_set_window(&record->window, 0x80u) &&
             ssd1681_write_plane_region(0x24u, s_frame, &record->window);
    }
    if (ok) {
        const uint32_t hold_start = HAL_GetTick();
        HAL_Delay(SSD1681_R10_STABLE_HOLD_TARGET_MS);
        record->hold_elapsed_ms = HAL_GetTick() - hold_start;
        record->hold_count = 1u;
        ok = record->hold_elapsed_ms >= SSD1681_R10_STABLE_HOLD_TARGET_MS &&
             record->hold_elapsed_ms <= SSD1681_R10_STABLE_HOLD_MAX_MS;
    }
    return ok;
}

static void ssd1681_r10_print_frame(const char *record_name,
                                     uint32_t sequence,
                                     uint8_t previous_x,
                                     uint8_t current_x,
                                     const ssd1681_r10_frame_record_t *record)
{
    char previous_label[8];
    if (previous_x == SSD1681_R10_WHITE_POSITION) {
        memcpy(previous_label, "white", sizeof("white"));
    } else {
        (void)snprintf(previous_label, sizeof(previous_label), "%u", (unsigned)previous_x);
    }
    printf("[epaper] phase_parallel_r10_ball schema=v5 %s=%lu previous_x=%s current_x=%u previous_frame_sha256=%s current_frame_sha256=%s previous_payload_sha256=%s current_payload_sha256=%s window_x_bytes=%u-%u window_y=%u-%u window_bytes=%lu changed_pixels=%u ww=%u wb=%u bw=%u bb=%u old_command=0x26 old_selector=1 old_writes=1 old_bytes=%lu new_command=0x24 new_selector=0 stage_writes_24=1 new_bytes=%lu control_22=0xCF controls_cf=1 refresh=0x20 refresh_20=1 busy_complete=1 busy_elapsed_ms=%lu post_sync_command=0x24 post_sync_writes=1 post_sync_bytes=%lu post_sync_refresh=0 hold_elapsed_ms=%lu hold_count=%u full_frame_writes=0 full_refreshes=0 controls_ff=0 controls_f7=0 controls_c7=0 controls_37=0 second_activations=0 retries=0 maintenance_refreshes=0 step_ok=1\r\n",
           record_name,
           (unsigned long)sequence,
           previous_label,
           (unsigned)current_x,
           ssd1681_r10_frame_sha256(previous_x),
           ssd1681_r10_frame_sha256(current_x),
           ssd1681_r10_payload_sha256(previous_x),
           ssd1681_r10_payload_sha256(current_x),
           (unsigned)record->window.x_start_byte,
           (unsigned)record->window.x_end_byte,
           (unsigned)record->window.y_start,
           (unsigned)record->window.y_end,
           (unsigned long)record->window_bytes,
           (unsigned)(record->wb + record->bw),
           (unsigned)record->ww,
           (unsigned)record->wb,
           (unsigned)record->bw,
           (unsigned)record->bb,
           (unsigned long)record->window_bytes,
           (unsigned long)record->window_bytes,
           (unsigned long)record->busy_elapsed_ms,
           (unsigned long)record->window_bytes,
           (unsigned long)record->hold_elapsed_ms,
           (unsigned)record->hold_count);
}

static void ssd1681_phase_parallel_r10_ball_diagnostic(void)
{
    const ssd1681_window_t initial_window = {
        .x_start_byte = 4u,
        .x_end_byte = 5u,
        .y_start = COMP_R10_BALL_DIAGNOSTIC_Y,
        .y_end = COMP_R10_BALL_DIAGNOSTIC_Y + COMP_R10_BALL_DIAGNOSTIC_SIZE - 1u,
        .changed = true,
    };
    uint8_t activations_completed = 0u;
    bool ok;

    ssd1681_read_only_gpio_init();
    printf("[epaper] phase_parallel_r10_ball schema=v5 armed qualification_activations=16 loop_limit=none popup_commands=0 telemetry_storage=host_ring_65536\r\n");
    printf("[epaper] phase_parallel_r10_ball schema=v5 start candidate=r10_actual_solid_ball geometry=12x12 black_pixels=112 y=80 positions=32,40,48,56,64 step_px=8 travel_px=32 path=ping_pong framebuffer=200x200 full_frame_bytes=5000 diff=full_previous_current union_window=exact_byte_aligned corridor_window=x4-9,y80-91,bytes72 lut_sha256=%s voltage_tail=221741A83258 old_command=0x26 old_selector=1 new_command=0x24 new_selector=0 post_sync_command=0x24 control=0xCF refresh=0x20 busy_limit_ms=600 busy_target_ms=475-550 stable_hold_target_ms=400-410 full_frame_writes=0 full_refreshes=0 controls_ff=0 controls_f7=0 controls_c7=0 controls_37=0 second_activations=0 retries=0 maintenance_refreshes=0 production_enabled=0\r\n",
           SSD1681_R10_R6_LUT_SHA256);

    ssd1681_point_probe_hard_reset();
    ok = ssd1681_wait_ready(0u, SSD1681_READY_TIMEOUT_MS) &&
         ssd1681_command(0x12u) &&
         ssd1681_wait_ready(0u, SSD1681_READY_TIMEOUT_MS) &&
         ssd1681_point_probe_set_window(&initial_window, 0x80u) &&
         ssd1681_command_data(0x32u, ssd1681_r10_r6_lut, 153u) &&
         ssd1681_command_data(0x3Fu, &ssd1681_r10_r6_lut[153], 1u) &&
         ssd1681_command_data(0x03u, &ssd1681_r10_r6_lut[154], 1u) &&
         ssd1681_command_data(0x04u, &ssd1681_r10_r6_lut[155], 3u) &&
         ssd1681_command_data(0x2Cu, &ssd1681_r10_r6_lut[158], 1u);
    printf("[epaper] phase_parallel_r10_ball schema=v5 lut_load command=0x32 payload_bytes=153 tails=3F:22,03:17,04:41A832,2C:58 candidate_sha256=%s loads=1 loaded=%u\r\n",
           SSD1681_R10_R6_LUT_SHA256,
           (unsigned)ok);

    const uint32_t qualification_start_ms = HAL_GetTick();
    for (uint8_t step = 0u;
         ok && step < COMP_R10_BALL_DIAGNOSTIC_ACTIVATIONS;
         ++step) {
        const uint8_t previous_x = comp_r10_ball_diagnostic_previous_x(step);
        const uint8_t current_x = comp_r10_ball_diagnostic_current_x(step);
        ssd1681_r10_frame_record_t record;
        ok = ssd1681_r10_execute_frame(previous_x, current_x, &record);
        if (ok) {
            ++activations_completed;
            ssd1681_r10_print_frame("qualification_frame",
                                     activations_completed,
                                     previous_x,
                                     current_x,
                                     &record);
        }
    }
    const uint32_t qualification_elapsed_ms = HAL_GetTick() - qualification_start_ms;
    if (!ok || activations_completed != COMP_R10_BALL_DIAGNOSTIC_ACTIVATIONS) {
        ssd1681_read_only_restore_bus();
        printf("[epaper] phase_parallel_r10_ball schema=v5 fault phase=qualification next_frame=%u reason=transport_invariant_or_busy_timeout retries=0 gpio_restore=%u\r\n",
               (unsigned)(activations_completed + 1u),
               (unsigned)ssd1681_read_only_bus_restored());
        printf("[epaper] phase_parallel_r10_ball schema=v5 qualification_result=no_go activations_completed=%u loop_started=0 popup_commands=0 qualification_elapsed_ms=%lu\r\n",
               (unsigned)activations_completed,
               (unsigned long)qualification_elapsed_ms);
        return;
    }

    printf("[epaper] phase_parallel_r10_ball schema=v5 qualification_result=ok activations_completed=16 controls_cf=16 refresh_20=16 busy_completions=16 writes_26=16 stage_writes_24=16 post_sync_24=16 post_sync_refresh=0 hold_count=16 stable_hold_target_ms=400-410 first_window_bytes=72 moving_window_bytes=72 corridor_window=x4-9,y80-91,bytes72 first_ww=464 first_wb=112 first_bw=0 first_bb=0 moving_ww=376 moving_wb=88 moving_bw=88 moving_bb=24 full_frame_writes=0 full_refreshes=0 controls_ff=0 controls_f7=0 controls_c7=0 controls_37=0 second_activations=0 lut_loads=1 voltage_tail_changes=0 retries=0 maintenance_refreshes=0 qualification_elapsed_ms=%lu bus_retained_for_loop=1\r\n",
           (unsigned long)qualification_elapsed_ms);
    printf("[epaper] phase_parallel_r10_ball schema=v5 observation_ready loop_limit=none next_previous_x=40 next_current_x=32 stable_hold_target_ms=400-410 corridor_window=x4-9,y80-91,bytes72 telemetry_storage=host_ring_65536 popup_eligible=1\r\n");

    uint8_t previous_x = 40u;
    uint8_t loop_index = 0u;
    uint32_t iteration = 1u;
    for (;;) {
        const uint8_t current_x = comp_r10_ball_diagnostic_positions[loop_index];
        ssd1681_r10_frame_record_t record;
        ok = ssd1681_r10_execute_frame(previous_x, current_x, &record);
        if (!ok) {
            ssd1681_read_only_restore_bus();
            printf("[epaper] phase_parallel_r10_ball schema=v5 fault phase=loop iteration=%lu previous_x=%u current_x=%u reason=transport_invariant_or_busy_timeout retries=0 loop_stopped=1 gpio_restore=%u\r\n",
                   (unsigned long)iteration,
                   (unsigned)previous_x,
                   (unsigned)current_x,
                   (unsigned)ssd1681_read_only_bus_restored());
            return;
        }
        ssd1681_r10_print_frame("loop_iteration", iteration, previous_x, current_x, &record);
        previous_x = current_x;
        loop_index = (uint8_t)((loop_index + 1u) %
                               COMP_R10_BALL_DIAGNOSTIC_LOOP_POSITIONS);
        if (iteration == UINT32_MAX) {
            ssd1681_read_only_restore_bus();
            printf("[epaper] phase_parallel_r10_ball schema=v5 fault phase=loop iteration=%lu reason=iteration_counter_exhausted retries=0 loop_stopped=1 gpio_restore=%u\r\n",
                   (unsigned long)iteration,
                   (unsigned)ssd1681_read_only_bus_restored());
            return;
        }
        ++iteration;
    }
}
#endif

