typedef struct {
    ssd1681_window_t pass1_window;
    ssd1681_window_t pass2_window;
    uint32_t pass1_reset_elapsed_ms;
    uint32_t pass2_reset_elapsed_ms;
    uint32_t pass1_busy_elapsed_ms;
    uint32_t pass2_busy_elapsed_ms;
    uint32_t transaction_elapsed_ms;
    uint32_t start_delta_ms;
    uint8_t activation_count;
    uint8_t source_resets;
    uint8_t ready_checks;
    uint8_t source_ff;
    uint8_t omitted_leading_columns;
} ssd1681_native_two_pass_record_t;

static bool ssd1681_native_two_pass_position_valid(uint8_t x)
{
#if COMPANION_EPAPER_SSD1681_R12_V22_CALM_CURIOUS_WARM_SAMPLER_DIAGNOSTIC
    return x == 32u || x == 44u || x == 56u;
#elif COMPANION_EPAPER_SSD1681_R11_NATIVE_CACHED_MODE2_THROW_ARC_DIAGNOSTIC
    return x == 32u || x == 44u || x == 56u || x == 68u || x == 80u ||
           x == 92u || x == 104u || x == 116u || x == 128u;
#else
    return x >= COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_X_START &&
           x <= COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_X_END &&
           ((x - COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_X_START) %
            COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_X_STEP) == 0u;
#endif
}

#if COMPANION_EPAPER_SSD1681_R12_V22_CALM_CURIOUS_WARM_SAMPLER_DIAGNOSTIC
static void ssd1681_r12_apply_normal_target_mapping(uint8_t *frame)
{
    uint8_t row[SSD1681_BYTES_PER_ROW];

    if (frame == NULL) {
        return;
    }
    for (uint16_t top = 0u; top < (SSD1681_HEIGHT / 2u); ++top) {
        const uint16_t bottom = (uint16_t)(SSD1681_HEIGHT - 1u - top);
        memcpy(row, &frame[(size_t)top * SSD1681_BYTES_PER_ROW], sizeof(row));
        memcpy(&frame[(size_t)top * SSD1681_BYTES_PER_ROW],
               &frame[(size_t)bottom * SSD1681_BYTES_PER_ROW], sizeof(row));
        memcpy(&frame[(size_t)bottom * SSD1681_BYTES_PER_ROW], row, sizeof(row));
    }
}

static uint8_t ssd1681_r12_frame_id(uint8_t internal_position)
{
    if (internal_position == 32u) return 0u;
    if (internal_position == 44u) return 1u;
    if (internal_position == 56u) return 2u;
    return UINT8_MAX;
}
#endif

static void ssd1681_native_two_pass_render(uint8_t *frame, uint8_t x)
{
#if COMPANION_EPAPER_SSD1681_R12_V22_CALM_CURIOUS_WARM_SAMPLER_DIAGNOSTIC
    const uint8_t *asset = x == 32u ? comp_r12_v22_calm_frame :
                           x == 44u ? comp_r12_v22_curious_frame :
                           x == 56u ? comp_r12_v22_warm_frame : NULL;
    if (asset != NULL) {
        memcpy(frame, asset, COMP_R12_V22_FRAME_BYTES);
        ssd1681_r12_apply_normal_target_mapping(frame);
    } else {
        memset(frame, 0xFF, SSD1681_FRAME_BYTES);
    }
    return;
#else
    uint8_t render_y = COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_Y;
#if COMPANION_EPAPER_SSD1681_R11_NATIVE_CACHED_MODE2_THROW_ARC_DIAGNOSTIC
    static const uint8_t arc_y[] = {112u, 91u, 76u, 67u, 64u, 67u, 76u, 91u, 112u};
    static const uint8_t arc_x[] = {32u, 44u, 56u, 68u, 80u, 92u, 104u, 116u, 128u};
    for (size_t i = 0u; i < sizeof(arc_x) / sizeof(arc_x[0]); ++i) {
        if (arc_x[i] == x) {
            render_y = arc_y[i];
            break;
        }
    }
#endif
    memset(frame, 0xFF, SSD1681_FRAME_BYTES);
    if (x == SSD1681_NATIVE_TWO_PASS_WHITE_POSITION) {
        return;
    }
    for (uint8_t row = 0u; row < COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_SIZE; ++row) {
        for (uint8_t col = 0u; col < COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_SIZE; ++col) {
            const int16_t dx = (int16_t)(2u * col) - COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_CENTER;
            const int16_t dy = (int16_t)(2u * row) - COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_CENTER;
            if ((dx * dx) + (dy * dy) <= COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_DISK_LIMIT) {
                const uint16_t pixel_x = (uint16_t)x + col;
                const size_t offset =
                    (size_t)(render_y + row) * SSD1681_BYTES_PER_ROW +
                    (pixel_x / 8u);
                frame[offset] &= (uint8_t)~(0x80u >> (pixel_x & 7u));
            }
        }
    }
#endif
}

static ssd1681_window_t ssd1681_native_two_pass_previous_black_window(void)
{
    ssd1681_window_t window = {
        .x_start_byte = SSD1681_BYTES_PER_ROW - 1u,
        .x_end_byte = 0u,
        .y_start = SSD1681_HEIGHT - 1u,
        .y_end = 0u,
        .changed = false,
    };
    for (uint16_t y = 0u; y < SSD1681_HEIGHT; ++y) {
        const size_t row = (size_t)y * SSD1681_BYTES_PER_ROW;
        for (uint8_t x = 0u; x < SSD1681_BYTES_PER_ROW; ++x) {
            if (s_previous_frame[row + x] == 0xFFu) {
                continue;
            }
            if (!window.changed || x < window.x_start_byte) window.x_start_byte = x;
            if (!window.changed || x > window.x_end_byte) window.x_end_byte = x;
            if (!window.changed || y < window.y_start) window.y_start = y;
            if (!window.changed || y > window.y_end) window.y_end = y;
            window.changed = true;
        }
    }
    return window;
}

static ssd1681_window_t ssd1681_native_guarded_corridor_window(void)
{
    ssd1681_window_t window = {
        .x_start_byte = COMPANION_EPAPER_SSD1681_R11_NATIVE_CACHED_MODE2_THROW_ARC_DIAGNOSTIC ? COMP_R11_NATIVE_CACHED_MODE2_THROW_ARC_X_START_BYTE : (COMPANION_EPAPER_SSD1681_R10_NATIVE_GUARDED_CORRIDOR_CACHED_MODE2_CADENCE_DIAGNOSTIC ? COMP_R10_NATIVE_GUARDED_CORRIDOR_CACHED_MODE2_CADENCE_X_START_BYTE : (COMPANION_EPAPER_SSD1681_R10_NATIVE_GUARDED_CORRIDOR_NO_RESET_CADENCE_DIAGNOSTIC ? COMP_R10_NATIVE_GUARDED_CORRIDOR_NO_RESET_CADENCE_X_START_BYTE : COMP_R10_NATIVE_GUARDED_CORRIDOR_LARGE_CADENCE_X_START_BYTE)),
        .x_end_byte = COMPANION_EPAPER_SSD1681_R11_NATIVE_CACHED_MODE2_THROW_ARC_DIAGNOSTIC ? COMP_R11_NATIVE_CACHED_MODE2_THROW_ARC_X_END_BYTE : (COMPANION_EPAPER_SSD1681_R10_NATIVE_GUARDED_CORRIDOR_CACHED_MODE2_CADENCE_DIAGNOSTIC ? COMP_R10_NATIVE_GUARDED_CORRIDOR_CACHED_MODE2_CADENCE_X_END_BYTE : (COMPANION_EPAPER_SSD1681_R10_NATIVE_GUARDED_CORRIDOR_NO_RESET_CADENCE_DIAGNOSTIC ? COMP_R10_NATIVE_GUARDED_CORRIDOR_NO_RESET_CADENCE_X_END_BYTE : COMP_R10_NATIVE_GUARDED_CORRIDOR_LARGE_CADENCE_X_END_BYTE)),
        .y_start = COMPANION_EPAPER_SSD1681_R11_NATIVE_CACHED_MODE2_THROW_ARC_DIAGNOSTIC ? COMP_R11_NATIVE_CACHED_MODE2_THROW_ARC_Y_START : (COMPANION_EPAPER_SSD1681_R10_NATIVE_GUARDED_CORRIDOR_CACHED_MODE2_CADENCE_DIAGNOSTIC ? COMP_R10_NATIVE_GUARDED_CORRIDOR_CACHED_MODE2_CADENCE_Y_START : (COMPANION_EPAPER_SSD1681_R10_NATIVE_GUARDED_CORRIDOR_NO_RESET_CADENCE_DIAGNOSTIC ? COMP_R10_NATIVE_GUARDED_CORRIDOR_NO_RESET_CADENCE_Y_START : COMP_R10_NATIVE_GUARDED_CORRIDOR_LARGE_CADENCE_Y_START)),
        .y_end = COMPANION_EPAPER_SSD1681_R11_NATIVE_CACHED_MODE2_THROW_ARC_DIAGNOSTIC ? COMP_R11_NATIVE_CACHED_MODE2_THROW_ARC_Y_END : (COMPANION_EPAPER_SSD1681_R10_NATIVE_GUARDED_CORRIDOR_CACHED_MODE2_CADENCE_DIAGNOSTIC ? COMP_R10_NATIVE_GUARDED_CORRIDOR_CACHED_MODE2_CADENCE_Y_END : (COMPANION_EPAPER_SSD1681_R10_NATIVE_GUARDED_CORRIDOR_NO_RESET_CADENCE_DIAGNOSTIC ? COMP_R10_NATIVE_GUARDED_CORRIDOR_NO_RESET_CADENCE_Y_END : COMP_R10_NATIVE_GUARDED_CORRIDOR_LARGE_CADENCE_Y_END)),
        .changed = true,
    };
    return window;
}

static uint8_t ssd1681_native_two_pass_omitted_columns(
    uint8_t current_x,
    const ssd1681_window_t *prior_window)
{
#if COMPANION_EPAPER_SSD1681_R12_V22_CALM_CURIOUS_WARM_SAMPLER_DIAGNOSTIC
    (void)current_x;
    (void)prior_window;
    return 0u;
#else
    const uint16_t left = (uint16_t)prior_window->x_start_byte * 8u;
    const uint16_t right = ((uint16_t)prior_window->x_end_byte + 1u) * 8u - 1u;
    uint8_t omitted = 0u;
    for (uint8_t col = 0u; col < COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_SIZE; ++col) {
        bool column_has_black = false;
        for (uint8_t row = 0u; row < COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_SIZE; ++row) {
            const int16_t dx = (int16_t)(2u * col) - COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_CENTER;
            const int16_t dy = (int16_t)(2u * row) - COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_CENTER;
            if ((dx * dx) + (dy * dy) <= COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_DISK_LIMIT) {
                column_has_black = true;
                break;
            }
        }
        if (column_has_black) {
            const uint16_t pixel_x = (uint16_t)current_x + col;
            if (pixel_x < left || pixel_x > right) {
                ++omitted;
            }
        }
    }
    return omitted;
#endif
}

